(5626248, 814729, 83313, '<td valign="top">Really cool looking. I love the wispy, slightly blurred bits.</td>', 'Really cool looking. I love the wispy, slightly blurred bits.', '2009-08-27 13:54:43.000000', NULL, 1),
(5626251, 816250, 83313, '<td valign="top">Not really impacting me much, I''m afraid. The subject is dark and the bright background is what draws my eye. If your camera has a good macro mode, a closer view of that moss growing on the twig would look pretty cool.</td>', 'Not really impacting me much, I''m afraid. The subject is dark and the bright background is what draws my eye. If your camera has a good macro mode, a closer view of that moss growing on the twig would look pretty cool.', '2009-08-27 14:01:56.000000', NULL, 1),
(5626252, 815011, 83313, '<td valign="top">Crayons always go over well. Nicely done.</td>', 'Crayons always go over well. Nicely done.', '2009-08-27 14:03:07.000000', NULL, 1),
(5626253, 815992, 83313, '<td valign="top">I''m going to hazard a guess that this could be grounds in a coffee pot. Pretty neat looking, whatever it is.</td>', 'I''m going to hazard a guess that this could be grounds in a coffee pot. Pretty neat looking, whatever it is.', '2009-08-27 14:04:13.000000', NULL, 1),
(5626256, 816232, 83313, '<td valign="top">Simple in concept, but very well executed. Love the details and coppery tones.</td>', 'Simple in concept, but very well executed. Love the details and coppery tones.', '2009-08-27 14:06:51.000000', NULL, 1),
(5626257, 815474, 83313, '<td valign="top">Pretty good, but something about it does not come off as strong to me as this sort of shot should be. Not sure if it is the lighting, sharpness, or what.</td>', 'Pretty good, but something about it does not come off as strong to me as this sort of shot should be. Not sure if it is the lighting, sharpness, or what.', '2009-08-27 14:08:56.000000', NULL, 1),
(5626260, 815980, 83313, '<td valign="top">Guilty as charged. I''m not sure this will do terribly well in voting, but it is keeping me looking at it, trying to figure it out. Grabbing my attention like that gets extra pointage.</td>', 'Guilty as charged. I''m not sure this will do terribly well in voting, but it is keeping me looking at it, trying to figure it out. Grabbing my attention like that gets extra pointage.', '2009-08-27 14:11:57.000000', NULL, 1),
(5626261, 816188, 83313, '<td valign="top">Just added to my vocabulary with this one.</td>', 'Just added to my vocabulary with this one.', '2009-08-27 14:13:27.000000', NULL, 1),
(5626264, 815662, 83313, '<td valign="top">Some finely lit clothespins there.</td>', 'Some finely lit clothespins there.', '2009-08-27 14:14:42.000000', NULL, 1),
(5626269, 816080, 83313, '<td valign="top">Comes off a bit dull and flat looking to me. I copied it into my image editor to see, and found the histogram to be flat on both light and dark ends. A quick levels adjustment would really brighten this up.</td>', 'Comes off a bit dull and flat looking to me. I copied it into my image editor to see, and found the histogram to be flat on both light and dark ends. A quick levels adjustment would really brighten this up.', '2009-08-27 14:18:34.000000', NULL, 1),
(5626273, 815993, 83313, '<td valign="top">Not sure what it is or is not, but in spite of the strong colors and details, this is not impacting me much. Maybe there is a slight cast that does not work for me, or not as sharp as my eye wants it to be. Wish I could be more specific for you.</td>', 'Not sure what it is or is not, but in spite of the strong colors and details, this is not impacting me much. Maybe there is a slight cast that does not work for me, or not as sharp as my eye wants it to be. Wish I could be more specific for you.', '2009-08-27 14:22:55.000000', NULL, 1),
(5626274, 816148, 83313, '<td valign="top">Not quite a macro, though I like it.</td>', 'Not quite a macro, though I like it.', '2009-08-27 14:24:02.000000', NULL, 1),
(5626275, 815815, 83313, '<td valign="top">Very blurry and grainy. Sometimes that works nicely for an abstract, but I''m afraid it''s not coming off well with me on this one.</td>', 'Very blurry and grainy. Sometimes that works nicely for an abstract, but I''m afraid it''s not coming off well with me on this one.', '2009-08-27 14:27:32.000000', NULL, 1),
