INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5628859, 815889, 67697, '<td valign="top">Very nice.  I liked the strong contrast.  The strong lines really pull the viewer into the photo.</td>', 'Very nice.  I liked the strong contrast.  The strong lines really pull the viewer into the photo.', '2009-08-31 01:43:00.000000', NULL, 0),
